import { Combobox as BaseCombobox } from '@base-ui/react/combobox';
import { Check, ChevronDown, Plus, RotateCw, Search, X } from 'lucide-react';
import { useId, type ReactNode, type Ref } from 'react';
import { usePortalContainer } from '../../utils/portal';
import { usePortalDir, useI18n } from '../../i18n/I18nProvider';
import { useFieldVariant } from '../../field-variant/field-variant-context';
import { cn } from '../../utils/cn';
import type { MeasuredRowOptions } from '../virtual-list/use-measured-rows';
import { WindowedComboboxList, useComboboxWindow, useVirtualOptionsKeyDown } from './WindowedCombobox';
import { Spinner } from '../spinner';
import { selectVariants } from '../select/select.variants';
import { comboboxVariants, type ComboboxVariantProps } from './combobox.variants';
import { useComboboxEnhancement } from './ComboboxRoot';
import { isSpecialItem, isSpecialItemGroup, type SpecialItem } from './specialItems';

export { Combobox, type ComboboxProps, type ComboboxAsyncProps } from './ComboboxRoot';

const s = comboboxVariants();

// Inputs also use aria-labelledby: while the popup is open Base UI aria-hides outside nodes
// (including the <label>), and aria-labelledby still resolves through hidden elements.
type InputBaseProps = Omit<BaseCombobox.Input.Props, 'className' | 'size'> & {
  className?: string;
  ref?: Ref<HTMLInputElement>;
  /** Visible label rendered above the field and bound to the input. Without it, pass `aria-label`. */
  label?: ReactNode;
};

export interface ComboboxInputProps extends InputBaseProps, ComboboxVariantProps {
  /** Show a clear button while a value is selected. */
  showClear?: boolean;
  clearLabel?: string;
  /** Accessible name of the chevron button. */
  triggerLabel?: string;
}

/** Single-select field: search icon, text input, optional clear, chevron trigger. */
export function ComboboxInput({
  size,
  variant,
  label,
  className,
  showClear = false,
  clearLabel: clearLabelProp,
  triggerLabel: triggerLabelProp,
  id,
  ...props
}: ComboboxInputProps) {
  const { t } = useI18n();
  const onKeyDown = useVirtualOptionsKeyDown(props.onKeyDown);
  const clearLabel = clearLabelProp ?? t('common.clearSelection');
  const triggerLabel = triggerLabelProp ?? t('common.showOptions');
  const autoId = useId();
  const inputId = id ?? autoId;
  const fieldVariant = useFieldVariant(variant);
  const v = comboboxVariants({ size, variant: fieldVariant });
  return (
    <>
      {label && (
        <label id={`${inputId}-label`} htmlFor={inputId} className={s.label()}>
          {label}
        </label>
      )}
      <BaseCombobox.InputGroup
        className={(state) =>
          cn(
            v.inputGroup(),
            fieldVariant !== 'outline' && (state.readOnly || props.readOnly) && 'bg-secondary/40',
            className,
          )
        }
      >
        <Search size={15} aria-hidden className={v.searchIcon()} />
        <BaseCombobox.Input
          id={inputId}
          aria-labelledby={label ? `${inputId}-label` : undefined}
          className={v.input()}
          {...props}
          onKeyDown={onKeyDown}
        />
        {showClear && (
          <BaseCombobox.Clear aria-label={clearLabel} className={v.iconButton()}>
            <X size={14} aria-hidden />
          </BaseCombobox.Clear>
        )}
        <BaseCombobox.Trigger aria-label={triggerLabel} className={cn('group', v.iconButton())}>
          <ChevronDown size={15} aria-hidden className={v.chevron()} />
        </BaseCombobox.Trigger>
      </BaseCombobox.InputGroup>
    </>
  );
}

export interface ComboboxChipsInputProps<Item> extends InputBaseProps {
  variant?: ComboboxVariantProps['variant'];
  /** Chip text for a selected item. Defaults to `item.label`, else `String(item)`. */
  getLabel?: (item: Item) => string;
  /** Accessible name of each chip's remove button. */
  removeLabel?: (label: string) => string;
}

function defaultLabel(item: unknown): string {
  if (item && typeof item === 'object' && 'label' in item) return String((item as { label: unknown }).label);
  return String(item);
}

/** Multi-select field: selected items as removable chips followed by the text input. Use with `<Combobox multiple>`. */
export function ComboboxChipsInput<Item = unknown>({
  variant,
  label,
  className,
  placeholder,
  getLabel = defaultLabel,
  removeLabel: removeLabelProp,
  id,
  ...props
}: ComboboxChipsInputProps<Item>) {
  const fieldVariant = useFieldVariant(variant);
  const v = comboboxVariants({ variant: fieldVariant });
  const { t } = useI18n();
  const onKeyDown = useVirtualOptionsKeyDown(props.onKeyDown);
  const removeLabel = removeLabelProp ?? ((l: string) => t('common.removeItem', { label: l }));
  const autoId = useId();
  const inputId = id ?? autoId;
  return (
    <>
      {label && (
        <label id={`${inputId}-label`} htmlFor={inputId} className={s.label()}>
          {label}
        </label>
      )}
      <BaseCombobox.InputGroup
        className={(state) =>
          cn(
            v.chipsGroup(),
            fieldVariant !== 'outline' && (state.readOnly || props.readOnly) && 'bg-secondary/40',
            className,
          )
        }
      >
        <BaseCombobox.Value>
          {(values: Item[]) => (
            <BaseCombobox.Chips className={s.chips()}>
              {values.map((item, i) => {
                const text = getLabel(item);
                return (
                  <BaseCombobox.Chip key={`${text}-${i}`} className={s.chip()} aria-label={text}>
                    {text}
                    <BaseCombobox.ChipRemove aria-label={removeLabel(text)} className={s.chipRemove()}>
                      <X size={11} strokeWidth={2.4} aria-hidden />
                    </BaseCombobox.ChipRemove>
                  </BaseCombobox.Chip>
                );
              })}
              <BaseCombobox.Input
                id={inputId}
                aria-labelledby={label ? `${inputId}-label` : undefined}
                placeholder={values.length ? undefined : placeholder}
                className={s.chipsInput()}
                {...props}
                onKeyDown={onKeyDown}
              />
            </BaseCombobox.Chips>
          )}
        </BaseCombobox.Value>
      </BaseCombobox.InputGroup>
    </>
  );
}

export interface ComboboxContentProps
  extends Omit<BaseCombobox.Popup.Props, 'className' | 'children'>, MeasuredRowOptions {
  className?: string;
  /** Shown (and announced) when no item matches the query. */
  emptyText?: ReactNode;
  side?: BaseCombobox.Positioner.Props['side'];
  align?: BaseCombobox.Positioner.Props['align'];
  sideOffset?: number;
  container?: BaseCombobox.Portal.Props['container'];
  /** List children: a render function `(item) => <ComboboxItem …/>`, or static items. */
  children?: BaseCombobox.List.Props['children'];
}

/** The popup: portal, positioner, popup surface, async status, empty state and listbox. */
export function ComboboxContent({
  className,
  emptyText: emptyTextProp,
  side = 'bottom',
  align = 'start',
  sideOffset = 6,
  container,
  children,
  itemHeight,
  estimatedItemHeight,
  overscan,
  ...props
}: ComboboxContentProps) {
  const portalContainer = usePortalContainer();
  const { t } = useI18n();
  const emptyText = emptyTextProp ?? t('common.noMatches');
  const dir = usePortalDir();
  const enh = useComboboxEnhancement();
  const windowed = useComboboxWindow();
  let list = children;
  if (enh && typeof children === 'function') {
    list = (item: unknown, index: number) =>
      isSpecialItemGroup(item) ? (
        item.items.map((special) => (
          <ComboboxSpecialItem key={`${special.__gntikSpecial}:${special.value}`} item={special} />
        ))
      ) : isSpecialItem(item) ? (
        <ComboboxSpecialItem key={`${item.__gntikSpecial}:${item.value}`} item={item} />
      ) : (
        children(item, index)
      );
  } else if (enh) {
    list = (
      <>
        {children}
        {enh.specials.map((item) => (
          <ComboboxSpecialItem key={item.__gntikSpecial} item={item} />
        ))}
      </>
    );
  }
  const busy = !!enh && (enh.loading || !!enh.error);
  const errorText =
    typeof enh?.errorText === 'function' ? enh.errorText(enh.error) : (enh?.errorText ?? t('combobox.loadFailed'));
  return (
    <BaseCombobox.Portal container={container ?? portalContainer}>
      <BaseCombobox.Positioner dir={dir} className={s.positioner()} side={side} align={align} sideOffset={sideOffset}>
        <BaseCombobox.Popup
          className={cn(
            s.popup(),
            windowed && typeof list === 'function' && 'flex flex-col overflow-hidden',
            className,
          )}
          {...props}
        >
          {enh && (
            <BaseCombobox.Status className={cn(s.status(), !!enh.error && !enh.loading && s.statusError())}>
              {enh.loading ? (
                <>
                  <Spinner size={13} />
                  {enh.loadingText ?? t('common.loading')}
                </>
              ) : enh.error ? (
                errorText
              ) : null}
            </BaseCombobox.Status>
          )}
          <BaseCombobox.Empty className={s.empty()}>{busy ? null : emptyText}</BaseCombobox.Empty>
          {windowed && typeof list === 'function' ? (
            <WindowedComboboxList
              aria-busy={enh?.loading || undefined}
              itemHeight={itemHeight}
              estimatedItemHeight={estimatedItemHeight}
              overscan={overscan}
            >
              {list}
            </WindowedComboboxList>
          ) : (
            <BaseCombobox.List className={s.list()} aria-busy={enh?.loading || undefined}>
              {list}
            </BaseCombobox.List>
          )}
        </BaseCombobox.Popup>
      </BaseCombobox.Positioner>
    </BaseCombobox.Portal>
  );
}

/** The built-in "Create “…”" and "Retry" rows (internal; MultiSelect reuses it). */
export function ComboboxSpecialItem({
  item,
  createLabel,
  ...props
}: BaseCombobox.Item.Props & {
  item: SpecialItem;
  createLabel?: (input: string) => ReactNode;
}) {
  const { t } = useI18n();
  const enh = useComboboxEnhancement();
  const label = createLabel ?? enh?.createLabel;
  const create = item.__gntikSpecial === 'create';
  return (
    <BaseCombobox.Item value={item} className={cn(s.item(), s.specialItem())} {...props}>
      <span className={s.itemContent()}>
        {create ? (
          <Plus size={14} aria-hidden className={s.specialIcon()} />
        ) : (
          <RotateCw size={14} aria-hidden className={s.specialIcon()} />
        )}
        <span className="truncate">
          {create ? (label?.(item.value) ?? t('combobox.create', { label: item.value })) : t('common.retry')}
        </span>
      </span>
    </BaseCombobox.Item>
  );
}

export interface ComboboxItemProps extends Omit<BaseCombobox.Item.Props, 'className'> {
  className?: string;
}

/** One option. Shows a check when selected. */
export function ComboboxItem({ className, children, ...props }: ComboboxItemProps) {
  return (
    <BaseCombobox.Item className={cn(s.item(), className)} {...props}>
      <span className={s.itemContent()}>{children}</span>
      <BaseCombobox.ItemIndicator className={s.indicator()}>
        <Check size={15} strokeWidth={2.4} aria-hidden />
      </BaseCombobox.ItemIndicator>
    </BaseCombobox.Item>
  );
}

export interface ComboboxGroupProps extends Omit<BaseCombobox.Group.Props, 'className' | 'items'> {
  className?: string;
  items?: readonly unknown[];
}

/** A labelled option group. Pass the filtered group's items to its Collection. */
export function ComboboxGroup({ className, ...props }: ComboboxGroupProps) {
  return <BaseCombobox.Group className={cn(className)} {...props} />;
}

export interface ComboboxGroupLabelProps extends Omit<BaseCombobox.GroupLabel.Props, 'className'> {
  className?: string;
}

const groupStyles = selectVariants();

export function ComboboxGroupLabel({ className, ...props }: ComboboxGroupLabelProps) {
  return <BaseCombobox.GroupLabel className={cn(groupStyles.groupLabel(), className)} {...props} />;
}

export interface ComboboxSeparatorProps extends Omit<BaseCombobox.Separator.Props, 'className'> {
  className?: string;
}

export function ComboboxSeparator({ className, ...props }: ComboboxSeparatorProps) {
  return <BaseCombobox.Separator className={cn(groupStyles.separator(), className)} {...props} />;
}

export interface ComboboxCollectionProps<Item = unknown> {
  children: (item: Item, index: number) => ReactNode;
  /** Optional container classes. Without this prop the collection renders no element. */
  className?: string;
}

/** Render the filtered items of the enclosing Group, or the root collection. */
export function ComboboxCollection<Item = unknown>({ className, children }: ComboboxCollectionProps<Item>) {
  const enhancement = useComboboxEnhancement();
  // With static Content children, Content owns the trailing built-in rows. Keep their
  // internal collection out of the consumer's group renderer and avoid rendering twice.
  const collection = (
    <BaseCombobox.Collection>
      {(item: Item, index: number) =>
        enhancement && (isSpecialItemGroup(item) || isSpecialItem(item)) ? null : children(item, index)
      }
    </BaseCombobox.Collection>
  );
  return className === undefined ? collection : <div className={cn(className)}>{collection}</div>;
}

/** Locale-aware matching for custom Combobox filters. */
export const useComboboxFilter = BaseCombobox.useFilter;

import { Combobox as BaseCombobox } from '@base-ui/react/combobox';
import { createContext, useContext, useRef, useState, type ReactNode } from 'react';
import {
  createItem,
  defaultItemLabel,
  hasExactLabel,
  isSpecialItem,
  retryItem,
  type SpecialItem,
  type SpecialItemGroup,
} from './specialItems';
import { isGroup, type OptionGroup } from './groupedItems';
import { WindowedComboboxRoot } from './WindowedCombobox';
import { useAsyncOptions, type LoadOptions } from './useAsyncOptions';

export interface ComboboxAsyncProps<Value> {
  /**
   * Async options: called (debounced) with the typed query and an `AbortSignal` that fires when the
   * request goes stale. While it is set, the returned options are shown as-is (no client filter).
   */
  loadOptions?: LoadOptions<Value | OptionGroup<Value>>;
  /** Debounce for `loadOptions`, in ms. Default 250. */
  debounceMs?: number;
  /**
   * Creatable: adds a "Create “…”" option while the typed text matches no option. Return the new
   * item (or a promise of it) to select it; return nothing to leave the selection as it is.
   */
  onCreate?: (input: string) => Value | void | Promise<Value | void>;
  /** Text of the create option. Default: "Create “{input}”". */
  createLabel?: (input: string) => ReactNode;
  /** Shown (and announced) while options load. Default: "Loading…". */
  loadingText?: ReactNode;
  /** Shown (and announced) when `loadOptions` rejects. Default: "Couldn’t load options." */
  errorText?: ReactNode | ((error: unknown) => ReactNode);
}

export type ComboboxProps<Value, Multiple extends boolean | undefined = false> = BaseCombobox.Root.Props<
  Value,
  Multiple
> &
  ComboboxAsyncProps<Value>;

interface ComboboxEnhancement {
  loading: boolean;
  error: unknown;
  loadingText?: ReactNode;
  errorText?: ComboboxAsyncProps<unknown>['errorText'];
  createLabel?: (input: string) => ReactNode;
  specials: SpecialItem[];
}

const EnhancementContext = createContext<ComboboxEnhancement | null>(null);

/** Async / creatable state for ComboboxContent; `null` for a plain Combobox. */
export const useComboboxEnhancement = () => useContext(EnhancementContext);

/**
 * Combobox state container: `items` (filtered by the input), `value` / `defaultValue` /
 * `onValueChange`, `multiple`. Items shaped `{ value, label }` need no extra config.
 * Add `loadOptions` for async options and `onCreate` for a "Create “…”" option.
 */
export function Combobox<Value, Multiple extends boolean | undefined = false>(props: ComboboxProps<Value, Multiple>) {
  const { loadOptions, debounceMs, onCreate, createLabel, loadingText, errorText, ...root } = props;
  const flat = root.items === undefined || (Array.isArray(root.items) && !root.items.some(isGroup));
  if (!loadOptions && !onCreate)
    return flat && root.virtualized && root.items ? (
      <WindowedComboboxRoot {...root} />
    ) : (
      <BaseCombobox.Root {...root} virtualized={flat ? root.virtualized : false} />
    );
  return (
    <EnhancedCombobox
      root={root as BaseCombobox.Root.Props<unknown, Multiple>}
      loadOptions={loadOptions as LoadOptions<unknown> | undefined}
      debounceMs={debounceMs}
      onCreate={onCreate as ComboboxAsyncProps<unknown>['onCreate']}
      createLabel={createLabel}
      loadingText={loadingText}
      errorText={errorText}
    />
  );
}

type ChangeDetails = BaseCombobox.Root.ChangeEventDetails;

function EnhancedCombobox<Multiple extends boolean | undefined>({
  root,
  loadOptions,
  debounceMs,
  onCreate,
  createLabel,
  loadingText,
  errorText,
}: ComboboxAsyncProps<unknown> & { root: BaseCombobox.Root.Props<unknown, Multiple> }) {
  const {
    items,
    value: valueProp,
    defaultValue,
    onValueChange,
    onInputValueChange,
    open: openProp,
    defaultOpen,
    onOpenChange,
    filter,
    itemToStringLabel,
    isItemEqualToValue,
    multiple,
    ...rest
  } = root;
  const core = BaseCombobox.useFilter();
  const [innerValue, setInnerValue] = useState<unknown>(defaultValue ?? (multiple ? [] : null));
  const value = valueProp !== undefined ? valueProp : innerValue;
  const [input, setInput] = useState(String(root.inputValue ?? root.defaultInputValue ?? ''));
  const [innerOpen, setInnerOpen] = useState(defaultOpen ?? false);
  const open = openProp ?? innerOpen;
  const keepOpen = useRef(false);

  const toLabel = (item: unknown) =>
    isSpecialItem(item) ? item.label : itemToStringLabel ? itemToStringLabel(item) : defaultItemLabel(item);
  const typed = input.trim();
  const selectedLabel = !multiple && value != null ? toLabel(value).trim() : null;
  // A single selection fills the input with its label: that is not a search.
  const query = selectedLabel !== null && selectedLabel === typed ? '' : typed;

  const remote = useAsyncOptions<unknown>(loadOptions, query, { debounceMs, enabled: open });
  const base: readonly unknown[] = loadOptions
    ? remote.error
      ? []
      : remote.items
    : ((items as readonly unknown[] | undefined) ?? []);
  const specials: SpecialItem[] = [];
  if (onCreate && query !== '' && !hasExactLabel(base, typed, toLabel)) specials.push(createItem(typed));
  if (loadOptions && remote.error && !remote.loading) specials.push(retryItem(input));
  const grouped = base.some(isGroup) || remote.items.some(isGroup) || (Array.isArray(items) && items.some(isGroup));
  const trailing: SpecialItemGroup = { __gntikSpecialGroup: true, items: specials };
  const allItems = grouped ? [...base, trailing] : [...base, ...specials];

  const commit = (next: unknown, details: ChangeDetails) => {
    setInnerValue(next);
    (onValueChange as ((v: unknown, d: ChangeDetails) => void) | undefined)?.(next, details);
  };

  const create = async (text: string, kept: unknown[] | null, details: ChangeDetails) => {
    const created = await onCreate?.(text);
    if (created === undefined || created === null) return;
    commit(kept ? [...kept, created] : created, details);
  };

  const handleValueChange = (next: unknown, details: ChangeDetails) => {
    const list = multiple && Array.isArray(next) ? next : null;
    const special = list ? list.find(isSpecialItem) : isSpecialItem(next) ? next : undefined;
    if (!special) return commit(next, details);
    const kept = list ? list.filter((item) => !isSpecialItem(item)) : null;
    if (special.__gntikSpecial === 'retry') {
      keepOpen.current = true;
      remote.reload();
      return;
    }
    void create(special.value.trim(), kept, details);
  };

  const enhancement: ComboboxEnhancement = {
    loading: remote.loading,
    error: remote.error,
    loadingText,
    errorText,
    createLabel,
    specials,
  };

  const virtualized = root.virtualized && !grouped;
  // Async results can change collection shape without remounting the input.
  const Root = root.virtualized ? WindowedComboboxRoot : BaseCombobox.Root;
  return (
    <EnhancementContext.Provider value={enhancement}>
      <Root<unknown, Multiple>
        {...rest}
        virtualized={virtualized}
        multiple={multiple}
        items={allItems}
        value={value as never}
        onValueChange={handleValueChange as never}
        open={open}
        onOpenChange={(next, details) => {
          if (!next && keepOpen.current) {
            keepOpen.current = false;
            return;
          }
          setInnerOpen(next);
          onOpenChange?.(next, details);
        }}
        onInputValueChange={(next, details) => {
          setInput(next);
          onInputValueChange?.(next, details);
        }}
        itemToStringLabel={toLabel}
        isItemEqualToValue={(a: unknown, b: unknown) =>
          isSpecialItem(a) || isSpecialItem(b)
            ? a === b
            : isItemEqualToValue
              ? isItemEqualToValue(a, b)
              : Object.is(a, b)
        }
        filter={
          loadOptions
            ? null
            : (item: unknown, q: string, toString?: (item: unknown) => string) =>
                isSpecialItem(item) ||
                filter === null ||
                (filter ? filter(item, q, toString) : core.contains(item, q, toString))
        }
      />
    </EnhancementContext.Provider>
  );
}

import { Combobox as BaseCombobox } from '@base-ui/react/combobox';
import { useRender } from '@base-ui/react/use-render';
import {
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useEffectEvent,
  useLayoutEffect,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import { useMeasuredRows, type MeasuredRowOptions } from '../virtual-list/use-measured-rows';

interface WindowState {
  active: number;
  query: string;
  selected: unknown;
  equal: (a: unknown, b: unknown) => boolean;
  batchHighlights: (navigate: () => void) => void;
}
const WindowContext = createContext<WindowState | null>(null);
export const useComboboxWindow = () => useContext(WindowContext);

/** Preserves the Base UI root API while exposing highlight and query to the window. */
export function WindowedComboboxRoot<Value, Multiple extends boolean | undefined = false>(
  props: BaseCombobox.Root.Props<Value, Multiple>,
) {
  const [active, setActive] = useState(-1);
  const [query, setQuery] = useState(String(props.defaultInputValue ?? ''));
  const [value, setValue] = useState<unknown>(props.defaultValue);
  type Highlight = Parameters<NonNullable<typeof props.onItemHighlighted>>;
  const navigation = useRef<{ batching: boolean; last: Highlight | null }>({ batching: false, last: null });
  const reportHighlight = (...args: Highlight) => {
    setActive(args[1].index);
    props.onItemHighlighted?.(...args);
  };
  const finishNavigation = () => {
    navigation.current.batching = false;
    const last = navigation.current.last;
    navigation.current.last = null;
    if (last) reportHighlight(...last);
  };
  const selected = props.value !== undefined ? props.value : value;
  return (
    <WindowContext.Provider
      value={
        props.virtualized === false
          ? null
          : {
              active,
              query: String(props.inputValue ?? query),
              selected: props.multiple ? (selected as unknown[])?.[0] : selected,
              equal: (props.isItemEqualToValue as WindowState['equal']) ?? Object.is,
              batchHighlights: (navigate) => {
                navigation.current.batching = true;
                navigation.current.last = null;
                try {
                  navigate();
                } finally {
                  finishNavigation();
                }
              },
            }
      }
    >
      <BaseCombobox.Root
        {...props}
        onItemHighlighted={(item, details) => {
          if (navigation.current.batching) navigation.current.last = [item, details];
          else reportHighlight(item, details);
        }}
        onInputValueChange={(next, details) => {
          props.onInputValueChange?.(next, details);
          if (!details.isCanceled) setQuery(next);
        }}
        onValueChange={(next, details) => {
          props.onValueChange?.(next, details);
          if (!details.isCanceled) setValue(next);
        }}
        onOpenChange={(next, details) => {
          props.onOpenChange?.(next, details);
          if (!next && !details.isCanceled) setActive(-1);
        }}
      />
    </WindowContext.Provider>
  );
}

export function WindowedComboboxList<Item = unknown>({
  children,
  'aria-busy': busy,
  ...options
}: MeasuredRowOptions & {
  children: (item: Item, index: number) => ReactNode;
  'aria-busy'?: boolean;
}) {
  const state = useComboboxWindow();
  const items = BaseCombobox.useFilteredItems<Item>();
  const selectedIndex = state?.selected != null ? items.findIndex((item) => state.equal(item, state.selected)) : -1;
  const active = state?.active ?? -1;
  const { indices, total, rowProps, setViewport, scrollTo, onScroll, pageSize } = useMeasuredRows(
    items,
    options,
    active >= 0 ? active : selectedIndex,
  );
  const scrollOnChange = useEffectEvent((index: number) => scrollTo(index));
  useLayoutEffect(() => {
    scrollOnChange(-1);
  }, [state?.query]);
  useLayoutEffect(() => {
    scrollOnChange(selectedIndex);
  }, [selectedIndex]);
  useLayoutEffect(() => {
    if (active >= 0) scrollOnChange(active);
  }, [active]);
  return (
    <BaseCombobox.List
      data-virtualized=""
      aria-busy={busy}
      ref={setViewport}
      className="max-h-64 min-h-0 overflow-y-auto outline-none data-empty:hidden"
      style={{ height: Math.min(total, 256) }}
      onScroll={onScroll}
      onKeyDown={(event) => {
        if (!state || !['Home', 'End', 'PageUp', 'PageDown'].includes(event.key) || items.length === 0) return;
        event.preventDefault();
        event.preventBaseUIHandler();
        const target =
          event.key === 'Home'
            ? 0
            : event.key === 'End'
              ? items.length - 1
              : Math.max(0, Math.min(items.length - 1, active + (event.key === 'PageDown' ? pageSize : -pageSize)));
        const key = target > active ? 'ArrowDown' : 'ArrowUp';
        // Base UI reserves Home/End for the input caret and has no public highlight setter.
        // Keep its navigation/selection state authoritative, reporting only the final highlight.
        state.batchHighlights(() => {
          for (let i = 0; i < Math.abs(target - active); i++) {
            event.currentTarget.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true }));
          }
        });
      }}
    >
      <div className="relative" style={{ height: total }}>
        {indices.map((index) => {
          const child = children(items[index]!, index);
          return isValidElement(child) ? (
            <WindowedOption
              key={child.key ?? index}
              child={child as ReactElement<BaseCombobox.Item.Props>}
              position={rowProps(index)}
              index={index}
            />
          ) : (
            child
          );
        })}
      </div>
    </BaseCombobox.List>
  );
}

function WindowedOption({
  child,
  position,
  index,
}: {
  child: ReactElement<BaseCombobox.Item.Props>;
  position: ReturnType<ReturnType<typeof useMeasuredRows>['rowProps']>;
  index: number;
}) {
  return useRender({
    ref: position.ref,
    render: cloneElement(child, {
      ...position,
      index,
      ref: child.props.ref,
      style: (state) => ({
        ...(typeof child.props.style === 'function' ? child.props.style(state) : child.props.style),
        ...position.style,
      }),
    }),
  });
}

/** Route list navigation keys through Base UI's public listbox keyboard interface. */
export const navigateVirtualOptions: NonNullable<BaseCombobox.Input.Props['onKeyDown']> = (event) => {
  if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return;
  if (!['Home', 'End', 'PageUp', 'PageDown'].includes(event.key)) return;
  const input = event.currentTarget;
  if (input.getAttribute('aria-expanded') !== 'true') return;
  const list = document.getElementById(input.getAttribute('aria-controls') ?? '');
  if (!list?.hasAttribute('data-virtualized')) return;
  event.preventDefault();
  event.preventBaseUIHandler();
  list.dispatchEvent(new KeyboardEvent('keydown', { key: event.key, bubbles: true }));
};

/** Share caller-first keyboard handling between the single and chips inputs. */
export function useVirtualOptionsKeyDown(
  handler: BaseCombobox.Input.Props['onKeyDown'],
): NonNullable<BaseCombobox.Input.Props['onKeyDown']> {
  const windowed = useComboboxWindow();
  return (event) => {
    handler?.(event);
    if (windowed) navigateVirtualOptions(event);
  };
}

