/** Base UI's grouped collection shape, shared by Combobox and MultiSelect. */
export interface OptionGroup<Item> {
  value?: string;
  items: readonly Item[];
}

export function isGroup<Item = unknown>(item: unknown): item is OptionGroup<Item> {
  return !!item && typeof item === 'object' && Array.isArray((item as { items?: unknown }).items);
}

import { isGroup, type OptionGroup } from './groupedItems';

/**
 * Built-in rows the kit adds to a combobox list: "Create “…”" (creatable) and "Retry" (after a
 * failed async load). They are real options, so the keyboard reaches them like any other row,
 * but selecting one never becomes the value.
 */
export interface SpecialItem {
  readonly __gntikSpecial: 'create' | 'retry';
  /** The typed text: selecting the row leaves the input as it was. */
  readonly value: string;
  readonly label: string;
}

export const createItem = (input: string): SpecialItem => ({ __gntikSpecial: 'create', value: input, label: input });
export const retryItem = (input: string): SpecialItem => ({ __gntikSpecial: 'retry', value: input, label: input });

export function isSpecialItem(item: unknown): item is SpecialItem {
  return !!item && typeof item === 'object' && '__gntikSpecial' in item;
}

/** `{ label }` → label, otherwise `String(item)` (Base UI's default for `{ value, label }` items). */
export function defaultItemLabel(item: unknown): string {
  if (item && typeof item === 'object' && 'label' in item) return String((item as { label: unknown }).label);
  return item == null ? '' : String(item);
}

/** `{ value }` → value, otherwise `String(item)`. */
export function defaultItemValue(item: unknown): string {
  if (item && typeof item === 'object' && 'value' in item) return String((item as { value: unknown }).value);
  return item == null ? '' : String(item);
}

/** Whether an option label already equals the typed text (case-insensitive). */
export function hasExactLabel<Item>(
  items: readonly (Item | OptionGroup<Item>)[],
  input: string,
  toLabel: (item: Item) => string,
): boolean {
  const q = input.trim().toLocaleLowerCase();
  return items.some((item) =>
    isGroup<Item>(item)
      ? hasExactLabel(item.items, input, toLabel)
      : !isSpecialItem(item) && toLabel(item).trim().toLocaleLowerCase() === q,
  );
}

export interface SpecialItemGroup extends OptionGroup<SpecialItem> {
  readonly __gntikSpecialGroup: true;
}

/** Trailing unlabelled collection, preserving Base UI's uniform grouped shape. */
export function isSpecialItemGroup(item: unknown): item is SpecialItemGroup {
  return isGroup(item) && '__gntikSpecialGroup' in item && item.__gntikSpecialGroup === true;
}

import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Loads the options for a query. Receives an `AbortSignal` that fires when the request goes stale
 * (the query changed, the popup closed or the component unmounted): pass it to `fetch`.
 */
export type LoadOptions<Item> = (query: string, context: { signal: AbortSignal }) => Promise<readonly Item[]>;

export interface UseAsyncOptionsConfig<Item> {
  /** Wait this long (ms) after the last keystroke before loading. Default 250; an empty query loads at once. */
  debounceMs?: number;
  /** Load only while true (e.g. while the popup is open). Results are kept when it turns false. */
  enabled?: boolean;
  /** Called with every successful result (e.g. to remember the labels of loaded options). */
  onResult?: (items: readonly Item[], query: string) => void;
}

export interface AsyncOptionsState<Item> {
  /** The latest loaded options (kept while a newer query loads). */
  items: readonly Item[];
  /** True from the moment the query changes until its result (or error) arrives. */
  loading: boolean;
  /** The last request's error, or `null`. */
  error: unknown;
  /** Runs the current query again (e.g. after an error). */
  reload: () => void;
}

interface Loaded<Item> {
  query: string | null;
  items: readonly Item[];
  error: unknown;
}

const isAbort = (e: unknown) => e instanceof DOMException && e.name === 'AbortError';

/**
 * Debounced, abortable option loading shared by Combobox, MultiSelect and SimpleSelect.
 * Without `loadOptions` it is inert (`loading` false, no items).
 */
export function useAsyncOptions<Item>(
  loadOptions: LoadOptions<Item> | undefined,
  query: string,
  { debounceMs = 250, enabled = true, onResult }: UseAsyncOptionsConfig<Item> = {},
): AsyncOptionsState<Item> {
  const [loaded, setLoaded] = useState<Loaded<Item>>({ query: null, items: [], error: null });
  const [reloadKey, setReloadKey] = useState(0);
  const loadRef = useRef(loadOptions);
  const onResultRef = useRef(onResult);
  useEffect(() => {
    loadRef.current = loadOptions;
    onResultRef.current = onResult;
  });

  const active = !!loadOptions && enabled;
  const stale = loaded.query !== query;

  useEffect(() => {
    const load = loadRef.current;
    if (!active || !load || !stale) return;
    const controller = new AbortController();
    const timer = window.setTimeout(
      () => {
        let request: Promise<readonly Item[]>;
        try {
          request = load(query, { signal: controller.signal });
        } catch (error) {
          request = Promise.reject(error);
        }
        request.then(
          (items) => {
            if (controller.signal.aborted) return;
            setLoaded({ query, items, error: null });
            onResultRef.current?.(items, query);
          },
          (error: unknown) => {
            if (controller.signal.aborted || isAbort(error)) return;
            setLoaded((prev) => ({ query, items: prev.items, error: error ?? new Error('Failed to load options') }));
          },
        );
      },
      query === '' ? 0 : debounceMs,
    );
    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
  }, [active, stale, query, debounceMs, reloadKey]);

  const reload = useCallback(() => {
    setLoaded((prev) => ({ ...prev, query: null, error: null }));
    setReloadKey((k) => k + 1);
  }, []);

  return {
    items: loaded.items,
    loading: active && stale,
    error: !stale ? loaded.error : null,
    reload,
  };
}

